def solve():
    import itertools

    def get_A(S):
        A = set()
        for f in S:
            for g in S:
                A.add(f - g)
        return A

    def get_B(A, r):
        B = set()
        for p in A:
            for q in A:
                B.add(3 * p * q * r)
        return B

    def get_C(A):
        C = set()
        for x in A:
            for y in A:
                for z in A:
                    for w in A:
                        C.add(x**2 + y**2 - z**2 - w**2)
        return C

    # Try different r values
    possible_r = [0, 1/3, -1/3, 2/3, -2/3]

    # Test for different S
    for r in possible_r:
        success = True
        # Test S = {0, 1, x} for various x
        for x in [2, 3, 4, 5, 10, 1.5, 2.5]:
            S = [0, 1, x]
            A = get_A(S)
            B = get_B(A, r)
            C = get_C(A)
            if not B.issubset(C):
                print(f"r={r} failed for S={S}")
                success = False
                break
        if success:
            print(f"r={r} passed")

solve()
